// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        string memory result = c.version();
        assertTrue(
            keccak256(abi.encodePacked(result)) == keccak256(abi.encodePacked("1.0.0")),
            "version must be 1.0.0"
        );
    }
}
